# Patch 2026-08-31: Preisniveau-Block konsolidieren (kPreis)
# Kurz-Antwort + 2 Karten vorn, volle 12-Zeilen-Tabelle in <details>-Aufklapper.
# Idempotent per Signatur: neuer Text enthaelt "data-preisdetail".
import base64, sys
P = "dashboard_v3.html"
ALT = base64.b64decode("")
NEU = base64.b64decode("")
s = open(P, "rb").read()
if NEU in s or b"data-preisdetail" in s:
    print("SKIP: Patch bereits angewendet"); sys.exit(0)
if s.count(ALT) != 1:
    print("FEHLER: Alttext nicht exakt 1x gefunden (%d)" % s.count(ALT)); sys.exit(1)
open(P, "wb").write(s.replace(ALT, NEU))
print("OK: kPreis ersetzt")
